123	/**
124	 * Reorder rules by an explicit list of rule ids (new first-match order). Only
125	 * ids that actually belong to the server are moved; anything else is ignored, so
126	 * a caller cannot reposition another tenant's rule.
127	 */
128	export async function reorderFirewallRules(serverId: string, orderedIds: string[]): Promise<{ error?: string }> {
129	  const { user } = await ownedServer(serverId);
130	  if (!Array.isArray(orderedIds) || orderedIds.length === 0) return { error: "Nothing to reorder." };
131	
132	  const owned = await db.firewallRule.findMany({ where: { serverId }, select: { id: true } });
133	  const ownedIds = new Set(owned.map((r) => r.id));
134	  const ids = orderedIds.filter((id) => ownedIds.has(id));
135	  if (ids.length === 0) return { error: "No matching rules to reorder." };
136	
137	  await db.$transaction(
138	    ids.map((id, index) =>
139	      db.firewallRule.update({ where: { id }, data: { position: index } })
140	    )
141	  );
142	
143	  await enqueueSync(serverId);
144	  await db.auditLog.create({
145	    data: { userId: user.id, action: "server.firewall_reorder", detail: `${serverId} ${ids.length} rules` },
146	  });
147	  revalidatePath(`/dashboard/servers/${serverId}`);
148	  return {};
149	}
