1	import { db } from "../lib/db";
2	import { connectionTarget, serverRootPassword } from "../lib/sftp";
3	import { withServerSsh, exec as sshExecOn } from "../lib/ssh-exec";
4	import { SANDBOX } from "../lib/sandbox";
5	import { validateRule, buildReconcileScript, FW_CHAIN, type ValidatedRule } from "../lib/firewall-rules";
6	import type { Job } from "@prisma/client";
7	
8	const CMD_TIMEOUT_MS = 60_000;
9	
10	/**
11	 * Apply a customer's inbound firewall to their guest, idempotently.
12	 *
13	 * MECHANISM: guest-side iptables over SSH, via the same connectionTarget()-based
14	 * plumbing (lib/ssh-exec.ts's withServerSsh/exec) every other control-panel
15	 * feature uses — host/port resolve to the server's dedicated IP, or its OWN
16	 * node's public IP + NAT-forwarded sshPort, never a hardcoded/private address.
17	 * The Proxmox per-VM firewall API was the alternative, but lib/proxmox.ts
18	 * exposes only a generic REST client with no firewall helper, and enabling it
19	 * requires flipping cluster/node/NIC firewall flags that interact with the
20	 * existing NAT model — a far larger, riskier change for guests that are already
21	 * reachable as root over SSH. So: guest iptables.
22	 *
23	 * SAFETY: the reconcile SCRIPT is built by lib/firewall-rules.ts from VALIDATED,
24	 * structured fields only. Each DB row is re-run through `validateRule` here
25	 * (defence in depth) before it can contribute a line; a row that fails is skipped
26	 * and logged, never interpolated. Ports are integers, protocol/action are closed
27	 * enums, and the source CIDR is regex-validated + normalised — so no raw customer
28	 * string (the free-text `comment` least of all) ever reaches the guest shell.
29	 *
30	 * IDEMPOTENT: the script creates the NXEON_FW chain once, ensures INPUT jumps to
31	 * it once, then FLUSHES only that chain and rebuilds it — so re-running yields
32	 * identical kernel state and never accumulates stale rules or touches the
33	 * customer's own INPUT rules.
34	 *
35	 * ANTI-LOCKOUT: the baseline always accepts loopback, ESTABLISHED/RELATED and
36	 * tcp/22, so SSH stays reachable no matter what the customer configures, and the
37	 * default DROP is appended only when they have at least one ALLOW rule.
38	 */
39	export async function syncFirewall(job: Job): Promise<void> {
40	  const serverId = job.serverId;
41	  if (!serverId) throw new Error("syncFirewall: job has no serverId");
42	
43	  const server = await db.server.findUnique({
44	    where: { id: serverId },
45	    include: {
46	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
47	      dedicatedIp: true,
48	      node: true,
49	    },
50	  });
51	  if (!server) {
52	    // Row is gone (server deleted); the cascade removed its rules too. Nothing to do.
53	    console.log(`[fw] server ${serverId} not found — skipping firewall sync`);
54	    return;
55	  }
56	
57	  // Don't fight the lifecycle: a suspended/deleting/not-yet-provisioned VM has no
58	  // reachable guest to configure. The rules stay in the DB and re-apply on the
59	  // next sync once the server is steady again.
60	  if (["SUSPENDED", "DELETING", "PENDING", "PROVISIONING", "REINSTALLING", "STOPPED", "ERROR"].includes(server.status)) {
61	    console.log(`[fw] server ${serverId} status=${server.status} — deferring firewall sync`);
62	    return;
63	  }
64	
65	  // Re-validate every ENABLED row through the SAME gate the action used. A row
66	  // that somehow got into the DB malformed is dropped from the applied set (and
67	  // reported) rather than allowed to break the build.
68	  const validated: ValidatedRule[] = [];
69	  for (const r of server.firewallRules) {
70	    if (!r.enabled) continue;
71	    const result = validateRule({
72	      action: r.action,
73	      protocol: r.protocol,
74	      portFrom: r.portFrom,
75	      portTo: r.portTo,
76	      sourceCidr: r.sourceCidr,
77	    });
78	    if (!result.ok) {
79	      console.error(`[fw] server ${serverId} rule ${r.id} rejected at apply: ${result.error}`);
80	      continue;
81	    }
82	    validated.push(result.rule);
83	  }
84	
85	  const script = buildReconcileScript(validated);
86	
87	  if (SANDBOX) {
88	    console.log(`[fw] SANDBOX — would apply ${validated.length} rule(s) to ${server.hostname}:\n${script}`);
89	    return;
90	  }
91	
92	  const password = serverRootPassword(server);
93	  if (!connectionTarget(server) || !password) {
94	    throw new Error(`syncFirewall: server ${serverId} has no reachable IP or root password`);
95	  }
96	
97	  // The script travels as a single-quoted payload to `bash -c` on the guest;
98	  // nothing here is assembled by a host shell.
99	  const wrapped = `bash -c ${shSingleQuote(script)}`;
100	
101	  try {
102	    const r = await withServerSsh(server, (conn) => sshExecOn(conn, wrapped, CMD_TIMEOUT_MS));
103	    if (r.code !== 0) {
104	      const out = `${r.stdout}${r.stderr ? `\n${r.stderr}` : ""}`.trim();
105	      throw new Error(
106	        `syncFirewall: applying ${FW_CHAIN} to ${server.hostname} failed — exit ${r.code ?? "?"}` +
107	          (out ? `: ${out.slice(0, 400)}` : "")
108	      );
109	    }
110	  } catch (e: any) {
111	    if (e instanceof Error && e.message.startsWith("syncFirewall:")) throw e;
112	    // Connection-level failure (timeout, unreachable, no password) — exec()
113	    // itself threw rather than returning a non-zero exit.
114	    throw new Error(`syncFirewall: applying ${FW_CHAIN} to ${server.hostname} failed — ${e?.message ?? e}`);
115	  }
116	
117	  console.log(`[fw] applied ${validated.length} rule(s) to ${server.hostname} (${FW_CHAIN})`);
118	}
119	
120	/** Single-quote a payload for a POSIX shell (`'` → `'\''`). */
121	function shSingleQuote(s: string): string {
122	  return `'${s.replace(/'/g, `'\\''`)}'`;
123	}
